from pathlib import Path
import json
P=Path(__file__).parent;E=P/'crossrail/elements'
f=E/'chart-line/element.css';s=f.read_text();s=s[:s.find('\n[data-el="crossrail-chart-line"] .pt{border-top:0}')]
r='[data-el="crossrail-chart-line"]'
s+='\n'+r+'{transform:translateX(0);anchor-scope:all}'+r+' .pt{border-top:0}'+r+' .pt::before,'+r+' .pt::after{content:"";position:fixed;left:anchor(var(--crossrail-prev) center);right:anchor(var(--crossrail-curr) center);pointer-events:none;transform:none;width:auto;height:auto;border-radius:0;background:linear-gradient(to bottom right,transparent calc(50% - 1px),var(--a1-7) calc(50% - 1px) calc(50% + 1px),transparent calc(50% + 1px));z-index:0}'+r+' .pt::before{top:anchor(var(--crossrail-curr) top);bottom:anchor(var(--crossrail-prev) top)}'+r+' .pt::after{top:anchor(var(--crossrail-prev) top);bottom:anchor(var(--crossrail-curr) top);background:linear-gradient(to top right,transparent calc(50% - 1px),var(--a1-7) calc(50% - 1px) calc(50% + 1px),transparent calc(50% + 1px))}'+r+' .pt:first-child::before,'+r+' .pt:first-child::after{display:none}'+r+' .pt b{z-index:1}'+r+' .pt b::after{content:"";position:absolute;left:50%;top:calc(100% + var(--gap-sm) - 5px);width:10px;height:10px;transform:translateX(-50%);background:var(--a1-7);border-radius:50%}'
for i in range(1,25):s+=f'{r} .pt:nth-child({i}){{anchor-name:--crossrail-p{i};--crossrail-curr:--crossrail-p{i};--crossrail-prev:--crossrail-p{max(1,i-1)};}}'
f.write_text(s+'\n');p=E/'chart-line/element.json';m=json.loads(p.read_text());m['tokenDefaults']={'--crossrail-curr':'--crossrail-p1','--crossrail-prev':'--crossrail-p1'};p.write_text(json.dumps(m,indent=2)+'\n')
f=E/'chart-area/element.css';s=f.read_text();s=s[:s.find('\n[data-el="crossrail-chart-area"] .series{background:none}')];f.write_text(s+'\n');p=E/'chart-area/element.json';m=json.loads(p.read_text());m['tokenDefaults']={};p.write_text(json.dumps(m,indent=2)+'\n')
f=E/'card/element.css';f.write_text(f.read_text()+'''\n[data-el="crossrail-card"] .name{min-height:calc(var(--type-28)*var(--name-line)*2)}[data-el="crossrail-card"] .note{min-height:calc(var(--type-18)*var(--body-line)*4)}@container(max-height:300px){[data-el="crossrail-card"] .parts{padding:var(--gap-sm)}[data-el="crossrail-card"] .name{font-size:var(--type-24);min-height:calc(var(--type-24)*var(--name-line)*2)}[data-el="crossrail-card"] .note{font-size:var(--type-16);min-height:calc(var(--type-16)*var(--body-line)*3)}[data-el="crossrail-card"] .mark{width:48px;height:48px}}@container(max-height:220px){[data-el="crossrail-card"]:has(.fig) .parts{display:grid;grid-template-columns:1fr 1fr;align-content:center;gap:var(--gap-sm)}[data-el="crossrail-card"]:has(.fig) .fig{grid-column:1;font-size:var(--type-36)}[data-el="crossrail-card"]:has(.fig) .name{grid-column:2;min-height:0;text-align:right;font-size:var(--type-22);padding:0;border:0}[data-el="crossrail-card"]:has(.fig) .note{grid-column:1 / -1;min-height:0;font-size:var(--type-16);border-top:1px solid var(--n-3);padding-top:var(--gap-sm)}}\n''')
f=E/'steps/element.css';f.write_text(f.read_text()+'''\n[data-el="crossrail-steps"].col .step{border:1px solid var(--n-3);border-radius:999px;padding:var(--gap-sm)}[data-el="crossrail-steps"].col .mark{clip-path:none;border-radius:50%;background:var(--page);color:var(--a1-7);border:1px solid var(--n-3);width:60px;height:60px}[data-el="crossrail-steps"].col .name{border:0;padding:0}\n''')
print('Removed fixture value selectors; universal anchors now link previous and current points; cards aligned')
